        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0030\") ... (node (ref \"J6\") (pin \"22\")) ... (node (ref \"R16\") (pin \"2\")))"
        },
        {
          "source": "spec",
          "quote": "\"Short R10, R10 for Core2 and CoreS3 / Short R9, R11 for others\""
        }
      ],
      "impact": "The alternative M5Stack GPIO pins are electrically tied together through the zero-ohm links. If those pins have different functions or are driven independently on the assembled core, this can cause signal contention and incorrect PWM behavior.",
      "confidence": 0.83
    }
  ],
  "summary": "The netlist shows both zero-ohm GPIO mapping options connected for each PWM channel, despite the specification calling for variant-specific jumper selection. This bridges the alternative M5Stack bus pins and can cause contention."
}

